void SettingViewBase::setupScreen()
{
    RS485_kbps.initialize();
    for (int i = 0; i < RS485_kbpsListItems.getNumberOfDrawables(); i++)
    {
        RS485_kbpsListItems[i].initialize();
    }
    for (int i = 0; i < RS485_kbpsSelectedListItems.getNumberOfDrawables(); i++)
    {
        RS485_kbpsSelectedListItems[i].initialize();
    }
    keyboard1.initialize();
}

